// Text copied from the PHP ApkDetailRenderer and SeoRenderer, via their actual
// methods in the read-only oracle container. Algorithm changes live elsewhere.
package site

import "encoding/json"

type legacyLabels struct {
	Detail map[string]string `json:"detail"`
	SEO    struct {
		TitleSuffix         string            `json:"title_suffix"`
		Keywords            []string          `json:"keywords"`
		OGLocale            string            `json:"og_locale"`
		OperatingSystem     string            `json:"operating_system"`
		ApplicationCategory string            `json:"application_category"`
		GallerySuffix       string            `json:"gallery_suffix"`
		PathSuffixes        map[string]string `json:"path_suffixes"`
	} `json:"seo"`
	Nav map[string]string `json:"nav"`
}

var legacyLabelBank = func() map[string]legacyLabels {
	var labels map[string]legacyLabels
	if err := json.Unmarshal([]byte(legacyLabelJSON), &labels); err != nil {
		panic(err)
	}
	return labels
}()

func legacyLabelsFor(lang string) legacyLabels {
	if labels, ok := legacyLabelBank[lang]; ok {
		return labels
	}
	return legacyLabelBank["en"]
}

